package io.homeassistant.companion.android.common.data.websocket.impl.entities

import kotlinx.serialization.Serializable

/**
 * Configuration of a dashboard as returned by the `lovelace/config` websocket command.
 * Only the fields needed by the app are decoded. A dashboard generated by a strategy has no [views].
 */
@Serializable
data class LovelaceConfigResponse(val title: String? = null, val views: List<LovelaceViewResponse> = emptyList())

/** A view of a dashboard, see [LovelaceConfigResponse]. */
@Serializable
data class LovelaceViewResponse(val title: String? = null, val path: String? = null, val icon: String? = null)
